/* Real one-Reforge bidirectional recovery in a background Web Worker.
 * Unlike the old drop solver, this NEVER assumes the original monster/Kadala
 * tooltip was generated by the Reforge value stream. The original photo is
 * evidence of item identity and class only; the R output supplies constraints.
 * Step 1: invert numerical R output for possible child seeds (full 2^32).
 * Step 2: invert MWC transition for possible parent seeds (full 2^32).
 * Step 3: replay actual Reforge; enforce quality, item, complete visible stats,
 * and child seed. One surviving pair is a model-inferred unique current seed.
 */
import {UniversalEngine} from './universal-engine.js';
import {generateRecoveryHypotheses,verifyHypothesis} from './universal-recovery.js';
import {matchesObservation} from './candidate-analysis.js';
const TOTAL=4294967296,BATCH=6000000,CHUNK=32;
let cancelled=false;
const progress=(message,extra={})=>self.postMessage({type:'progress',message,...extra});
const verify=(engine,item,seed,hypotheses)=>hypotheses.some(h=>verifyHypothesis(engine,item,seed,h));
const enough=obs=>obs?.quality==='normal'&&Array.isArray(obs.lines)&&
 obs.lines.filter(x=>x.stem!=='Sockets'&&Number.isFinite(Number(x.value))).length>=4;
self.onmessage=async({data:d})=>{
 if(d?.type==='cancel'){cancelled=true;return;}
 if(d?.type!=='recover-reforge')return;
 cancelled=false;
 try{
  const engine=new UniversalEngine(d.gameData,d.hero,true);
  const item=engine.item(d.itemId);
  if(!item)throw Error('Unknown game item.');
  const obs=d.observation;
  if(!enough(obs))throw Error('Enter a NORMAL Reforge result with at least four numeric affix values; use the full visible tooltip.');
  if(obs.itemId!==item.id)throw Error('Reforge must preserve the original item identity.');
  if(d.sourceObservation&&d.sourceObservation.itemId!==item.id)throw Error('Drop item and Reforge result must refer to the same item.');
  const hypotheses=generateRecoveryHypotheses(engine,item,obs,{maxHypotheses:512});
  if(!hypotheses.length)throw Error('No numeric interpretation matches this Reforge result.');
  const resp=await fetch(new URL('../solver/scan.wasm',import.meta.url),{cache:'no-store'});
  if(!resp.ok)throw Error('The compiled bidirectional seed solver is missing.');
  const {instance}=await WebAssembly.instantiate(await resp.arrayBuffer());
  const w=instance.exports;
  if(typeof w.scan_parents!=='function'||typeof w.set_child_seed!=='function')
   throw Error('Old WASM solver: rebuild the v0.5 bidirectional binary.');
  const children=new Set();
  let verifiedNumeric=0,passes=0;
  for(let offset=0;offset<hypotheses.length;offset+=CHUNK){
   const hs=hypotheses.slice(offset,offset+CHUNK);
   w.set_pre_steps(item.armor?2:1);
   w.set_hyp_count(hs.length);
   hs.forEach((h,index)=>{
    w.set_hyp_length(index,h.constraints.length);
    h.constraints.forEach(({m,r},j)=>w.set_hyp_constraint(index,j,m,r));
   });
   for(let start=0;start<TOTAL;start+=BATCH){
    if(cancelled)throw Error('Seed recovery cancelled.');
    const n=w.scan_multi(start,Math.min(BATCH,TOTAL-start));
    if(w.was_overflow())throw Error('Too many child candidates in one batch. Provide more of the visible Reforge stats.');
    for(let j=0;j<n;j++){
     const seed=w.result_at(j)>>>0;
     if(!children.has(seed)&&verify(engine,item,seed,hs)){children.add(seed);verifiedNumeric++;}
    }
    if(start%(BATCH*10)===0||start+BATCH>=TOTAL)
     progress('Step 1/2 · searching post-Reforge seeds',{
      phase:'children',checked:offset*TOTAL+start+Math.min(BATCH,TOTAL-start),
      total:Math.ceil(hypotheses.length/CHUNK)*TOTAL,found:children.size});
   }
   passes++;
  }
  const valid=[...children];
  if(!valid.length)throw Error('No child seed reproduces this Reforge result. Check the numbers, percent signs, item class, or Mystic edits.');
  if(valid.length>8192)throw Error(`${valid.length} possible post-Reforge seeds: too many for a safe parent scan. A second genuine Reforge observation or more precise stat values are required.`);
  w.set_child_count(valid.length);
  valid.forEach((seed,i)=>w.set_child_seed(i,seed));
  w.set_parent_quality(0);
  const pairs=new Map();
  for(let start=0;start<TOTAL;start+=BATCH){
   if(cancelled)throw Error('Seed recovery cancelled.');
   const n=w.scan_parents(start,Math.min(BATCH,TOTAL-start));
   if(w.parent_was_overflow())throw Error('Too many predecessor candidates in one batch. The result is ambiguous; do not spend materials.');
   for(let j=0;j<n;j++){
    const parent=w.parent_result_at(j)>>>0,child=w.parent_child_at(j)>>>0;
    const predicted=engine.reforge(item,parent);
    if(predicted.seed!==child||predicted.quality!==obs.quality)continue;
    if(!matchesObservation(predicted,obs))continue;
    // Extra safeguard: require that every visible numeric result was given.
    const numberOfStats=obs.lines.filter(x=>x.stem!=='Sockets').length;
    if(numberOfStats<predicted.lines.length)continue;
    const key=parent+':'+child;
    pairs.set(key,{parent,current:child,quality:predicted.quality,draws:predicted.draws,
      item:predicted.item,affixes:predicted.affixes.map(a=>a.stem)});
   }
   if(start%(BATCH*10)===0||start+BATCH>=TOTAL)
    progress('Step 2/2 · replaying complete Reforge predecessors',{
     phase:'parents',checked:start+Math.min(BATCH,TOTAL-start),total:TOTAL,found:pairs.size});
  }
  const solutions=[...pairs.values()];
  self.postMessage({type:'complete',solutions,
    postReforgeNumericCandidates:valid.length,reconstruction:'bidirectional-real-reforge',
    unique:solutions.length===1,
    note:solutions.length===1?'Unique model-inferred transition. Validate the first recipe checkpoint in game.':
      'More than one or zero valid predecessor pairs; do NOT claim a unique seed.'});
 }catch(err){self.postMessage({type:'error',message:String(err?.message||err)});}
};
